using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Tax rate below 0 throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> DiscountTestCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m, "No discount" };
            yield return new object[] { 100.00m, 10m, 90.00m, "10% off" };
            yield return new object[] { 100.00m, 50m, 50.00m, "50% off" };
            yield return new object[] { 100.00m, 100m, 0.00m, "100% off (free)" };
            yield return new object[] { 49.99m, 25m, 37.4925m, "Fractional result" };
            yield return new object[] { 0.00m, 50m, 0.00m, "Zero price stays zero" };
            yield return new object[] { 1000.00m, 33.33m, 666.70m, "Repeating decimal discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result, $"Failed for scenario: {scenario}");
    }

    public static IEnumerable<object[]> InvalidDiscountTestCases
    {
        get
        {
            yield return new object[] { 100.00m, -1m, "Negative discount" };
            yield return new object[] { 100.00m, 100.01m, "Discount exceeds 100%" };
            yield return new object[] { 50.00m, 200m, "200% discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountTestCases))]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent, string scenario)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName, $"Failed for scenario: {scenario}");
    }

    // --- FormatPrice: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, "$", "$10.00", DisplayName = "Default dollar symbol")]
    [DataRow(10.50, "€", "€10.50", DisplayName = "Euro symbol")]
    [DataRow(0.00, "$", "$0.00", DisplayName = "Zero formats correctly")]
    [DataRow(1234.5, "£", "£1234.50", DisplayName = "Pads to two decimals")]
    public void FormatPrice_WithValidInputs_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

